 private void applyLaunchIntent(){Intent i=getIntent();
   if(i.getBooleanExtra("play_latest",false)){playLatestPending=true;showTab(1);handler.postDelayed(this::playLatest,350);}
   if("STOP".equals(i.getAction())||i.getBooleanExtra("stop_capture",false)){wantStart=false;wantTest=false;service.stopCapture();refresh();return;}
   try{JSONObject changes=new JSONObject();for(String key:new String[]{"width","height","fov"})if(i.hasExtra(key))changes.put(key,i.getExtras().get(key));if(i.hasExtra("segment_seconds"))changes.put("segmentSeconds",i.getIntExtra("segment_seconds",60));else if(i.hasExtra("record_seconds"))changes.put("segmentSeconds",i.getIntExtra("record_seconds",60));if(i.hasExtra("auto_start"))changes.put("autoStart",i.getBooleanExtra("auto_start",false));if(changes.length()>0){service.settings().apply(changes);if(i.hasExtra("fov"))for(int k=0;k<4;k++){float[] p=service.lensProfile().get(k);p[4]=i.getIntExtra("fov",100);service.lensProfile().set(k,p);}service.reloadSettings();}}catch(Exception error){toast("הגדרת ניסיון: "+error.getMessage());}
   if(i.hasExtra("ui_tab"))showTab(Math.max(0,Math.min(3,i.getIntExtra("ui_tab",0))));if(i.getBooleanExtra("test_storage",false)&&!service.isCapturing()&&!service.isRecording())thumbnails.execute(()->{JSONObject report=StorageSelfTest.run(getApplicationContext());handler.post(()->toast("בדיקת אחסון: "+report.optInt("passed")+" הצליחו / "+report.optInt("failed")+" שגיאות"));});eventPending=i.getBooleanExtra("event_lock",false);snapshotPending=i.getBooleanExtra("snapshot",false);
   if(i.hasExtra("gpu")||i.hasExtra("lens")||i.hasExtra("fps")||i.hasExtra("bitrate"))service.configure(i.getBooleanExtra("gpu",service.usesGpu()),i.getBooleanExtra("lens",service.lensCorrected()),i.getIntExtra("fps",service.fpsTarget()),i.getIntExtra("bitrate",service.bitrateTarget()));
   if(i.hasExtra("codec")||i.hasExtra("scale"))service.configureEncoding(i.hasExtra("codec")?i.getStringExtra("codec"):service.preferredCodec(),i.getIntExtra("scale",service.recordingScale()));
   if(i.getBooleanExtra("short_gpu_test",false)){service.runShortGpuTest();wantStart=false;}
   if(wantStart){service.testRequested=wantTest;service.testDurationMs=Math.max(1000,Math.min(120000,i.getIntExtra("test_ms",5000)));if(i.getBooleanExtra("file_replay",false))service.startFileReplayForTest();else service.startCapture();wantStart=false;}
   if(i.getBooleanExtra("start_dvr",false))service.startDvr();attachSurface();refresh();
 }
