  if(service!=null){try{VehicleTelemetry.Snapshot s=service.telemetry();if(s!=null&&s.speedKmh!=null&&s.speedAgeMs<=5000){speed.setText(String.format(Locale.US,"%.0f",s.speedKmh));speedSource.setText("קמ״ש · "+s.speedSource);}else{speed.setText("—");speedSource.setText("קמ״ש · אין נתונים עדכניים");}}catch(Exception ignored){speed.setText("—");}JSONObject d=service.diagnostics();elapsed.setText(duration(d.optLong("record_seconds",0)));recordInfo.setText(service.recordStatus());if(tab==0&&surface!=null){surface.setVisibility(service.usesGpu()?View.VISIBLE:View.GONE);grid.setVisibility(service.usesGpu()?View.INVISIBLE:View.VISIBLE);status.setText(service.status()+String.format(Locale.US,"\nממוצע תצוגה %.1f FPS · ממוצע הקלטה %.1f FPS",d.optDouble("preview_actual_fps",0),d.optDouble("actual_record_fps",0)));mainAction.setText(active?"■  עצור הקלטה":"●  התחל הקלטה");mainAction.setBackground(shape(active?RED:GOLD,12));JSONObject settings=service.settings().snapshot();profile.setText((service.usesGpu()?"GPU":"CPU")+" · "+settings.optInt("width")+"×"+settings.optInt("height")+" · "+settings.optInt("fps")+" FPS hedef · FOV "+settings.optInt("fov")+"°");grid.invalidate();hud.invalidate();}if(tab==3&&diagnostic!=null)try{diagnostic.setText(d.toString(2));}catch(Exception ignored){}if(eventPending&&service.isRecording()){eventPending=false;service.lockEvent();}if(snapshotPending&&service.canRecord()){snapshotPending=false;service.snapshotNow();}if(wantTest&&!testStarted&&service.canRecord()){service.toggleRecord(false);testStarted=true;}if(wantReplay&&service.canRecord()){service.freezeSourceForTest();wantReplay=false;}if(getIntent().getBooleanExtra("capture_ui",false)&&!snapshotDone&&playback==null&&!playLatestPending&&(tab!=0||service.canRecord())){snapshotDone=true;handler.postDelayed(()->captureUi("ui-snapshot.png",true),700);}}
