 private void reloadClips(){galleryAt=SystemClock.elapsedRealtime();JSONArray records=storage.records();clips.clear();String today=new SimpleDateFormat("yyyyMMdd",Locale.US).format(new Date());for(int k=0;k<records.length();k++){JSONObject r=records.optJSONObject(k);if(r==null)continue;if(filter==1&&!r.optBoolean("locked"))continue;if(filter==2&&!today.equals(new SimpleDateFormat("yyyyMMdd",Locale.US).format(new Date(r.optLong("date")))))continue;clips.add(r);}galleryCount=records.length();if(clipAdapter!=null)clipAdapter.notifyDataSetChanged();}
