 private void loadThumbnail(ImageView image,String uri){image.setTag(uri);Bitmap cached=cache.get(uri);if(cached!=null){image.setImageBitmap(cached);return;}image.setImageDrawable(null);synchronized(pending){if(!pending.add(uri))return;}thumbnails.execute(()->{Bitmap result=null;MediaMetadataRetriever retriever=new MediaMetadataRetriever();try{retriever.setDataSource(this,OwnClipProvider.forClip(uri));result=retriever.getScaledFrameAtTime(0,MediaMetadataRetriever.OPTION_CLOSEST_SYNC,320,180);}catch(Exception ignored){}finally{try{retriever.release();}catch(Exception ignored){}}final Bitmap bitmap=result;handler.post(()->{synchronized(pending){pending.remove(uri);}if(bitmap!=null){cache.put(uri,bitmap);if(uri.equals(image.getTag()))image.setImageBitmap(bitmap);}});});}
