 private void playLatest(){if(!playLatestPending||isFinishing())return;playLatestPending=false;JSONArray records=storage.records();if(records.length()==0){toast("אין הקלטה שהושלמה להפעלה");return;}playClip(records.optJSONObject(0).optString("uri"));}
