 private void editLens(int slot){if(!editable())return;float[] values=service.lensProfile().get(slot);String[] labels={"מרכז X (0–1)","מרכז Y (0–1)","מיקוד X / רוחב","מיקוד Y / גובה","שדה ראייה אופקי","רדיאלי k1","רדיאלי k2","זום"};LinearLayout box=dialogBox();EditText[] fields=new EditText[8];for(int k=0;k<8;k++)fields[k]=number(box,labels[k],String.format(Locale.US,"%.5f",values[k]));AlertDialog dialog=new AlertDialog.Builder(this).setTitle("מצלמה "+(slot+1)+" פרופיל עדשה").setView(scroll(box)).setPositiveButton("שמור",null).setNeutralButton("אפס הכול",(d,w)->{service.lensProfile().reset();service.reloadSettings();toast("פרופילי העדשה אופסו");}).setNegativeButton("בטל",null).create();dialog.setOnShowListener(d->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{try{float[] p=new float[8];for(int k=0;k<8;k++)p[k]=Float.parseFloat(fields[k].getText().toString().replace(',','.'));service.lensProfile().set(slot,p);service.reloadSettings();dialog.dismiss();}catch(Exception e){toast("הגדרת עדשה לא תקינה: "+e.getMessage());}}));dialog.show();}
 private void selectFolder(){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT_TREE);i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION|Intent.FLAG_GRANT_PREFIX_URI_PERMISSION);try{startActivityForResult(i,61);}catch(Exception e){toast("במערכת זו אין בורר תיקיות: "+e.getMessage());}}
 @Override public void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==61&&result==RESULT_OK&&data!=null&&data.getData()!=null){try{Uri uri=data.getData();int grants=data.getFlags()&(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION);getContentResolver().takePersistableUriPermission(uri,grants);storage.setTree(uri);toast("תיקיית USB נשמרה");}catch(Exception e){toast("אין גישה לתיקייה: "+e.getMessage());}}}
 private void traceDialog(){JSONObject s=settings();LinearLayout box=dialogBox();CheckBox on=check(box,"שמור יומן מפורט לקובץ",s.optBoolean("diagnosticLog",false));box.addView(text("הקובץ נשמר בתיקייה:\n"+new DvrLog(this).file().getAbsolutePath(),12,MUTED));box.addView(text("לשליפה: מנהל קבצים או adb pull. היומן מוגבל ל-2 MB ומתחלף אוטומטית.",12,MUTED));showSave("יומן אבחון",box,()->save(patch("diagnosticLog",on.isChecked())));}
 private void captureLogcat(){new Thread(()->{String text=dumpLogcat();String result=new DvrLog(this).saveSnapshot(text);handler.post(()->toast(result==null?"שמירת הלוג נכשלה":"נשמר: "+result));}).start();}
 private String dumpLogcat(){StringBuilder out=new StringBuilder();try{java.lang.Process p=Runtime.getRuntime().exec(new String[]{"logcat","-d","-t","3000","-v","threadtime"});try(BufferedReader in=new BufferedReader(new InputStreamReader(p.getInputStream(),"UTF-8"))){String line;while((line=in.readLine())!=null){String lower=line.toLowerCase(Locale.US);for(String key:LOG_KEYS)if(lower.contains(key)){out.append(line).append('\n');break;}}}p.waitFor();}catch(Exception e){out.append("logcat לא זמין: ").append(e.getMessage()).append('\n');}return out.toString();}
 private void showTrace(){TextView view=text(new DvrLog(this).tail(160),11,WHITE);view.setTypeface(Typeface.MONOSPACE);view.setTextIsSelectable(true);ScrollView scroll=new ScrollView(this);scroll.setPadding(dp(14),dp(8),dp(14),dp(8));scroll.addView(view);new AlertDialog.Builder(this).setTitle("יומן אבחון").setView(scroll).setPositiveButton("סגור",null).show();}
 private void diagnosticsUi(){LinearLayout page=column();page.addView(text("אבחון מערכת חי",23,WHITE));page.addView(text("מקור אמיתי, קצב פריימים, אוטומציה ומצב אחסון",12,MUTED));space(page,12);diagnostic=text("ממתין לחיבור השירות",12,GOLD);diagnostic.setTypeface(Typeface.MONOSPACE);diagnostic.setTextIsSelectable(true);diagnostic.setPadding(dp(15),dp(15),dp(15),dp(15));diagnostic.setBackground(shape(CARD,14));LinearLayout tools=row();Button show=button("▤  הצג יומן",v->showTrace());tools.addView(show,new LinearLayout.LayoutParams(0,dp(48),1));Button clear=button("✕  נקה יומן",v->{new DvrLog(this).clear();toast("היומן נוקה");});LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(0,dp(48),1);cp.leftMargin=dp(8);tools.addView(clear,cp);Button capture=button("⬇  לכוד logcat",v->captureLogcat());LinearLayout.LayoutParams gp=new LinearLayout.LayoutParams(0,dp(48),1);gp.leftMargin=dp(8);tools.addView(capture,gp);page.addView(tools);space(page,10);ScrollView scroll=new ScrollView(this);scroll.addView(diagnostic);page.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));body.addView(page,new FrameLayout.LayoutParams(-1,-1));}
 private RectF fit(float w,float h){float rw=w,rh=w*.75f;if(rh>h){rh=h;rw=h/0.75f;}return new RectF((w-rw)/2,(h-rh)/2,(w+rw)/2,(h+rh)/2);}
 private int cameraCount(){if(service==null)return 4;try{return Math.max(1,Math.min(4,((Number)service.getClass().getMethod("activeCameraCount").invoke(service)).intValue()));}catch(Exception ignored){return 4;}}
 private RectF cell(int slot,float w,float h){RectF area=fit(w,h);if(selected>=0||cameraCount()==1)return area;float cw=area.width()/2,ch=area.height()/2;return new RectF(area.left+(slot%2)*cw,area.top+(slot/2)*ch,area.left+(slot%2+1)*cw,area.top+(slot/2+1)*ch);}
 private void pickCamera(float x,float y){if(cameraCount()==1){selected=-1;if(service!=null)service.selectCamera(-1);return;}RectF area=fit(preview.getWidth(),preview.getHeight());if(!area.contains(x,y))return;if(selected>=0)selected=-1;else selected=(x>=area.centerX()?1:0)+(y>=area.centerY()?2:0);if(selected>=cameraCount())selected=-1;if(service!=null)service.selectCamera(selected);grid.invalidate();hud.invalidate();}
 private final class PreviewGrid extends View{private final Paint p=new Paint(Paint.ANTI_ALIAS_FLAG|Paint.FILTER_BITMAP_FLAG);PreviewGrid(){super(MainActivity.this);}protected void onDraw(Canvas canvas){canvas.drawColor(CARD);for(int k=0;k<cameraCount();k++){if(selected>=0&&k!=selected)continue;RectF r=cell(k,getWidth(),getHeight());Bitmap bitmap=service==null?null:service.image(k);if(bitmap!=null&&!bitmap.isRecycled()){p.setAlpha(service.isFresh(k)?255:80);canvas.drawBitmap(bitmap,null,r,p);p.setAlpha(255);}else{p.setColor(RAISED);canvas.drawRect(r,p);p.setColor(BORDER);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(dp(2));RectF icon=new RectF(r.centerX()-dp(25),r.centerY()-dp(25),r.centerX()+dp(25),r.centerY()+dp(10));canvas.drawRoundRect(icon,dp(8),dp(8),p);canvas.drawCircle(r.centerX(),r.centerY()-dp(7),dp(8),p);p.setStyle(Paint.Style.FILL);p.setColor(MUTED);p.setTextSize(dp(11));p.setTextAlign(Paint.Align.CENTER);canvas.drawText("ממתין לתמונה",r.centerX(),r.centerY()+dp(35),p);}}}}
 private final class PreviewHud extends View{private final Paint p=new Paint(Paint.ANTI_ALIAS_FLAG);PreviewHud(){super(MainActivity.this);}protected void onDraw(Canvas c){for(int k=0;k<cameraCount();k++){if(selected>=0&&selected!=k)continue;RectF r=cell(k,getWidth(),getHeight());p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(dp(1));p.setColor(BORDER);c.drawRect(r,p);p.setStyle(Paint.Style.FILL);p.setColor(0xd9101216);RectF pill=new RectF(r.left+dp(12),r.top+dp(12),r.left+dp(133),r.top+dp(39));c.drawRoundRect(pill,dp(8),dp(8),p);p.setColor(service!=null&&service.isFresh(k)?GOLD:MUTED);c.drawCircle(pill.left+dp(12),pill.centerY(),dp(3),p);p.setTextSize(dp(10));p.setTypeface(Typeface.DEFAULT_BOLD);c.drawText("מצלמה "+(k+1),pill.left+dp(23),pill.centerY()+dp(3),p);if(service!=null&&service.isRecording()){p.setColor(RED);c.drawCircle(r.right-dp(20),r.top+dp(24),dp(4),p);}}}public boolean onTouchEvent(MotionEvent e){if(e.getAction()==MotionEvent.ACTION_UP){pickCamera(e.getX(),e.getY());performClick();}return true;}public boolean performClick(){super.performClick();return true;}}
 private void captureUi(String name,boolean gpu){try{View decor=getWindow().getDecorView();if(decor.getWidth()==0||decor.getHeight()==0)return;Bitmap bitmap=Bitmap.createBitmap(decor.getWidth(),decor.getHeight(),Bitmap.Config.ARGB_8888);decor.draw(new Canvas(bitmap));if(gpu&&surface!=null&&gpuSurface!=null&&gpuSurface.isValid()&&surface.getWidth()>0){Bitmap camera=Bitmap.createBitmap(surface.getWidth(),surface.getHeight(),Bitmap.Config.ARGB_8888);PixelCopy.request(surface,camera,result->{if(result==PixelCopy.SUCCESS){int[] at=new int[2];surface.getLocationInWindow(at);Canvas composite=new Canvas(bitmap);composite.drawBitmap(camera,at[0],at[1],null);composite.save();composite.translate(at[0],at[1]);if(hud!=null)hud.draw(composite);composite.restore();writePng(camera,"gpu-preview.png");}writePng(bitmap,name);},handler);}else writePng(bitmap,name);}catch(Exception ignored){}}
 private void writePng(Bitmap bitmap,String name){try(FileOutputStream out=new FileOutputStream(new File(getFilesDir(),name))){bitmap.compress(Bitmap.CompressFormat.PNG,100,out);}catch(Exception ignored){}}
 private LinearLayout column(){LinearLayout v=new LinearLayout(this);v.setOrientation(LinearLayout.VERTICAL);return v;}private LinearLayout row(){LinearLayout v=new LinearLayout(this);v.setGravity(Gravity.CENTER_VERTICAL);return v;}
 private TextView text(String value,float size,int color){TextView v=new TextView(this);v.setText(value);v.setTextSize(CAR?size*1.25f:size);v.setTextColor(color);v.setFontFeatureSettings("tnum");return v;}
 private Button button(String title,View.OnClickListener click){Button b=new Button(this);b.setText(title);b.setTextSize(CAR?16:13);b.setAllCaps(false);b.setTextColor(WHITE);b.setPadding(dp(9),0,dp(9),0);b.setMinHeight(0);b.setMinimumHeight(0);b.setBackground(shape(RAISED,12));b.setOnClickListener(click);return b;}
 private GradientDrawable shape(int fill,float radius){GradientDrawable d=new GradientDrawable();d.setColor(fill);d.setCornerRadius(dp(radius));d.setStroke(dp(1),BORDER);return d;}
 private void space(LinearLayout parent,int height){parent.addView(new View(this),new LinearLayout.LayoutParams(1,dp(height)));}
 private int dp(float x){return Math.round(x*getResources().getDisplayMetrics().density);}
 private void toast(String s){Toast.makeText(this,s==null?"הפעולה לא הושלמה":s,Toast.LENGTH_LONG).show();}
 private LinearLayout dialogBox(){LinearLayout box=column();box.setPadding(dp(20),dp(12),dp(20),dp(15));box.setBackgroundColor(CARD);return box;}
 private View scroll(View child){ScrollView v=new ScrollView(this);v.addView(child);return v;}
 private CheckBox check(LinearLayout parent,String label,boolean checked){CheckBox c=new CheckBox(this);c.setText(label);c.setTextColor(WHITE);c.setTextSize(14);c.setChecked(checked);parent.addView(c);return c;}
 private EditText number(LinearLayout parent,String label,String value){parent.addView(text(label,13,MUTED));EditText edit=new EditText(this);edit.setTextColor(WHITE);edit.setSingleLine(true);edit.setInputType(android.text.InputType.TYPE_CLASS_NUMBER|android.text.InputType.TYPE_NUMBER_FLAG_DECIMAL|android.text.InputType.TYPE_NUMBER_FLAG_SIGNED);edit.setText(value);parent.addView(edit,new LinearLayout.LayoutParams(-1,dp(48)));return edit;}
 private Spinner spinner(LinearLayout parent,String label,String[] values,int selected){parent.addView(text(label,13,MUTED));Spinner spinner=new Spinner(this);ArrayAdapter<String> adapter=new ArrayAdapter<String>(this,android.R.layout.simple_spinner_item,values){public View getView(int p,View v,ViewGroup group){TextView t=(TextView)super.getView(p,v,group);t.setTextColor(WHITE);t.setTextSize(14);return t;}};adapter.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item);spinner.setAdapter(adapter);spinner.setSelection(Math.max(0,selected));parent.addView(spinner,new LinearLayout.LayoutParams(-1,dp(48)));return spinner;}
 private void showSave(String title,LinearLayout box,Runnable save){new AlertDialog.Builder(this).setTitle(title).setView(scroll(box)).setPositiveButton("שמור",(d,w)->save.run()).setNegativeButton("בטל",null).show();}
 private int index(int[] a,int value){for(int k=0;k<a.length;k++)if(a[k]==value)return k;return 0;}private int index(String[] a,String value){for(int k=0;k<a.length;k++)if(a[k].equals(value))return k;return 0;}
 private static String duration(long seconds){seconds=Math.max(0,seconds);return seconds>=3600?String.format(Locale.US,"%02d:%02d:%02d",seconds/3600,(seconds/60)%60,seconds%60):String.format(Locale.US,"%02d:%02d",seconds/60,seconds%60);}
 @Override protected void onResume(){super.onResume();resumed=true;handler.removeCallbacks(ticker);handler.post(ticker);attachSurface();}
 @Override protected void onPause(){resumed=false;handler.removeCallbacks(ticker);detachSurface();super.onPause();}
 @Override protected void onDestroy(){if(playback!=null)playback.close();handler.removeCallbacksAndMessages(null);detachSurface();if(bound){unbindService(connection);bound=false;}thumbnails.shutdown();super.onDestroy();}
 @Override public void onBackPressed(){if(tab!=0)showTab(0);else super.onBackPressed();}
